import{_ as t,o as a,c as i,a3 as o}from"./chunks/framework.B5WAEDB7.js";const h=JSON.parse('{"title":"WheelOS | Integrated Autonomous Driving Solutions","titleTemplate":false,"description":"Short-distance autonomous transport solutions for manufacturing, healthcare, retail, logistics campuses and specialized sites, with bilingual engineering knowledge and evidence.","frontmatter":{"layout":"home","title":"WheelOS | Integrated Autonomous Driving Solutions","titleTemplate":false,"description":"Short-distance autonomous transport solutions for manufacturing, healthcare, retail, logistics campuses and specialized sites, with bilingual engineering knowledge and evidence.","status":"Product specification","content_type":"landing","keywords":["autonomous driving","solutions","engineering knowledge","evidence","WheelOS"],"decision_summary":"WheelOS supports repetitive short-distance transport for factories, hospitals, retailers, logistics parks and large institutions through application screening, an integrated autonomous-driving kit and project services.","best_for":["frequent short-distance transport","fixed routes","standardized handoffs","controlled-site low-speed operation","a clear operating owner"],"not_for":["low-frequency demonstrations","unconfirmed chassis interfaces","unresolved regulation or insurance","parcel last-mile delivery"],"next_action":"Submit the transport task for a fit assessment, then discuss kit configuration, integration and commercial structure.","cta_url":"mailto:support@wheelos.cn?subject=WheelOS%20short-distance%20transport%20assessment","hero":{"name":"WheelOS","text":"Make repetitive short-distance transport deployable","tagline":"For factories, hospitals, retailers, logistics parks and large institutions, assess the application first, then integrate and validate it with a pre-integrated WheelOS platform.","actions":[{"theme":"brand","text":"Assess your transport task","link":"/en/solutions/applications"},{"theme":"alt","text":"Explore the integrated kit","link":"/en/solutions/integrated-autonomous-driving-kit"}]},"features":[{"title":"Screen the application first","details":"Use frequency, routes, handoffs, operating ownership and compliance to decide whether autonomous transport fits.","link":"/en/solutions/applications#decision-summary"},{"title":"See how the solution is built","details":"From site discovery and vehicle integration through replay validation and pilot operation, each stage has deliverables and exit criteria.","link":"/en/solutions/delivery-process"},{"title":"Discuss the commercial model","details":"System purchase, fixed-route service, vehicle leasing/capacity and software/operations subscription.","link":"/en/solutions/applications#commercial-models"},{"title":"Keep product and evidence separate","details":"Product specifications define the offer; only an evidence record with environment and metrics supports a verified claim.","link":"/en/about/principles"}]},"headers":[],"relativePath":"en/index.md","filePath":"en/index.md","lastUpdated":1794216847000}'),s={name:"en/index.md"};function n(r,e,d,l,c,p){return a(),i("div",null,[...e[0]||(e[0]=[o('<h2 id="locate-your-task-quickly" tabindex="-1">Locate your task quickly <a class="header-anchor" href="#locate-your-task-quickly" aria-label="Permalink to &quot;Locate your task quickly&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Business task</th><th>Typical customer</th><th>Suggested entry</th></tr></thead><tbody><tr><td>Material movement among warehouses, workshops and lines</td><td>Manufacturers and industrial parks</td><td><a href="/en/solutions/applications#manufacturing">Manufacturing</a></td></tr><tr><td>Specimen and supply movement among hospitals and laboratories</td><td>Hospital groups and medical laboratories</td><td><a href="/en/solutions/applications#medical-logistics">Medical logistics</a></td></tr><tr><td>Small-batch replenishment from a regional warehouse to nearby stores</td><td>Retail, fresh-food and restaurant chains</td><td><a href="/en/solutions/applications#retail-replenishment">Retail replenishment</a></td></tr><tr><td>Transfers among warehouses, docks and staging areas</td><td>Logistics parks and warehouse operators</td><td><a href="/en/solutions/applications#logistics-campus">Logistics campus</a></td></tr><tr><td>Food, linen and consumables for campus operations</td><td>Universities, hotels and property managers</td><td><a href="/en/solutions/applications#campus-logistics">Campus logistics</a></td></tr><tr><td>Fixed cargo shuttling and horizontal transport</td><td>Ports, airports and specialized sites</td><td><a href="/en/solutions/applications#specialized-sites">Specialized sites</a></td></tr></tbody></table><p><a href="/en/solutions/applications">Open the full decision guide: priorities, value metrics, commercial models and fit checklist →</a></p><h2 id="build-the-project-like-a-house" tabindex="-1">Build the project like a house <a class="header-anchor" href="#build-the-project-like-a-house" aria-label="Permalink to &quot;Build the project like a house&quot;">​</a></h2><p>Autonomous driving is not a one-step black box. We recommend seven visible stages: application discovery, boundary design, vehicle and sensors, software and data, replay validation, pilot operation and expansion assessment. Each stage exposes inputs, outputs, metrics, risks and unresolved issues.</p><p><a href="/en/solutions/delivery-process">View the seven-stage delivery process, exit criteria and pilot metrics →</a></p><h2 id="product-portfolio" tabindex="-1">Product portfolio <a class="header-anchor" href="#product-portfolio" aria-label="Permalink to &quot;Product portfolio&quot;">​</a></h2><p>The core product is the <a href="/en/solutions/integrated-autonomous-driving-kit">Integrated Autonomous Driving Kit</a>, which combines compute, sensors, time synchronization, a baseline autonomy stack and developer tools. Site adaptation, calibration, maps, training and simulation are project services whose scope requires confirmation.</p><h2 id="a-faster-route-from-prototype-to-real-world-testing" tabindex="-1">A faster route from prototype to real-world testing <a class="header-anchor" href="#a-faster-route-from-prototype-to-real-world-testing" aria-label="Permalink to &quot;A faster route from prototype to real-world testing&quot;">​</a></h2><p>Low-speed autonomous vehicle projects usually spend too much time aligning sensors, timestamps, drivers, coordinate frames, software modules and chassis interfaces. The WheelOS Integrated Autonomous Driving Kit turns those dependencies into a defined starting point.</p><div class="solution-grid"><div class="solution-card"><span class="solution-card__index">01 / START</span><h3>One reference architecture</h3><p>Compute, sensors, time synchronization, data recording and autonomous-driving modules are organized around a shared interface.</p></div><div class="solution-card"><span class="solution-card__index">02 / BUILD</span><h3>Room for your own IP</h3><p>Focus on your vehicle, site and algorithms while retaining access to APIs, data and standard CAN control interfaces.</p></div><div class="solution-card"><span class="solution-card__index">03 / VALIDATE</span><h3>Evidence you can reproduce</h3><p>Use record-and-replay workflows, calibration tools and visible system state to investigate failures and compare changes.</p></div></div><h2 id="designed-for-controlled-environments" tabindex="-1">Designed for controlled environments <a class="header-anchor" href="#designed-for-controlled-environments" aria-label="Permalink to &quot;Designed for controlled environments&quot;">​</a></h2><p>The kit is intended for engineering evaluation and deployment in manufacturing, healthcare, retail, logistics and campus transport tasks, as well as other controlled or semi-controlled sites. Typical platforms include low-speed delivery, logistics, patrol, cleaning, vending and special-purpose vehicles.</p><div class="solution-callout"><p><strong>Clear scope:</strong> The kit is not a certified production autonomous-driving system. Site risk assessment, regulatory approval and vehicle-level functional safety remain part of the customer project.</p></div><h2 id="verified-knowledge-and-product-scope-stay-separate" tabindex="-1">Verified knowledge and product scope stay separate <a class="header-anchor" href="#verified-knowledge-and-product-scope-stay-separate" aria-label="Permalink to &quot;Verified knowledge and product scope stay separate&quot;">​</a></h2><p>WheelOS uses three principles: AI-native retrieval, evidence-gated knowledge and explicit product boundaries. A <code>Product specification</code> describes configuration and delivery scope. <code>Verified</code> requires a reproducible evidence record with environment, metrics, raw results and review.</p><p>Start with <a href="/en/about/how-to-read">how to use this knowledge base</a>, or read the <a href="/en/about/principles">repository principles</a>.</p><h2 id="talk-to-an-engineer-before-you-specify-the-project" tabindex="-1">Talk to an engineer before you specify the project <a class="header-anchor" href="#talk-to-an-engineer-before-you-specify-the-project" aria-label="Permalink to &quot;Talk to an engineer before you specify the project&quot;">​</a></h2><p>Send us the vehicle type, site, route, speed target, drive-by-wire interface and timeline. We will help identify the right configuration and the main integration risks.</p><div class="solution-cta"><div><h2>Plan your first autonomous vehicle build</h2><p>Open the English product page for specifications, deliverables, chassis requirements and a reference price.</p></div><div class="solution-actions"><a class="primary" href="/en/solutions/integrated-autonomous-driving-kit">View the kit</a><a href="/en/knowledge/">Browse engineering knowledge</a></div></div>',20)])])}const m=t(s,[["render",n]]);export{h as __pageData,m as default};
